<?php
declare(strict_types=1);
function xmlText(string $s):string{return htmlspecialchars(preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/','',$s),ENT_XML1|ENT_QUOTES,'UTF-8');}
function zipStored(array $files):string{$body='';$central='';$count=0;foreach($files as $name=>$data){$len=strlen($data);$crc=crc32($data);$offset=strlen($body);$body.=pack('VvvvvvVVVvv',0x04034b50,20,0,0,0,33,$crc,$len,$len,strlen($name),0).$name.$data;$central.=pack('VvvvvvvVVVvvvvvVV',0x02014b50,20,20,0,0,0,33,$crc,$len,$len,strlen($name),0,0,0,0,0,$offset).$name;$count++;}return $body.$central.pack('VvvvvVVv',0x06054b50,0,0,$count,$count,strlen($central),strlen($body),0);}
function excelColumn(int $n):string{$out='';do{$out=chr(65+$n%26).$out;$n=intdiv($n,26)-1;}while($n>=0);return $out;}
function xlsxFile(array $headers,array $rows,array $numeric):string{$xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';$all=array_merge([$headers],$rows);foreach($all as $i=>$row){$xml.='<row r="'.($i+1).'">';foreach($row as $j=>$value){$ref=excelColumn($j).($i+1);if($i>0&&in_array($j,$numeric,true))$xml.='<c r="'.$ref.'" s="1"><v>'.xmlText((string)$value).'</v></c>';else $xml.='<c r="'.$ref.'" t="inlineStr"><is><t xml:space="preserve">'.xmlText((string)$value).'</t></is></c>';}$xml.='</row>';}$xml.='</sheetData></worksheet>';
    return zipStored(['[Content_Types].xml'=>'<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>',
    '_rels/.rels'=>'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
    'xl/workbook.xml'=>'<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Domiciliaciones" sheetId="1" r:id="rId1"/></sheets></workbook>',
    'xl/_rels/workbook.xml.rels'=>'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>',
    'xl/styles.xml'=>'<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="2" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>','xl/worksheets/sheet1.xml'=>$xml]);
}
function bankFile(array $profile,array $items):string{$mapping=json_decode($profile['mapping_json'],true);$headers=array_column($mapping,'header');$rows=[];$numeric=[];foreach($mapping as $i=>$map)if($map['field']==='amount')$numeric[]=$i;foreach($items as $item){$row=[];foreach($mapping as $map){$field=$map['field'];$v=$field==='constant'?($map['value']??''):($item[$field]??'');if($field==='amount')$v=number_format(((int)$v)/100,2,$profile['format']==='xlsx'?'.':$profile['decimal_separator'],'');$row[]=(string)$v;}$rows[]=$row;}if($profile['format']==='xlsx')return xlsxFile($headers,$rows,$numeric);
    $f=fopen('php://temp','r+');fwrite($f,"\xEF\xBB\xBF");foreach(array_merge([$headers],$rows) as $row){$safe=array_map(fn($s)=>preg_match('/^[\s]*[=+@\-]/u',$s)?"'".$s:$s,$row);fputcsv($f,$safe,$profile['delimiter'],'"','');}rewind($f);$bytes=stream_get_contents($f);fclose($f);return $bytes;
}
